import{_ as e,o,c as s,a3 as r}from"./chunks/framework.BFeCKmyl.js";const m=JSON.parse('{"title":"Filtro nas listas de preferências do processo","description":"","frontmatter":{"title":"Filtro nas listas de preferências do processo","id":"eproc-filtro-preferencias-processo","plataforma":"eproc","grupo":"Painel do processo","plano":"free","desde":"1.4.0","padrao":"ligado"},"headers":[],"relativePath":"funcionalidades/eproc-filtro-preferencias-processo.md","filePath":"funcionalidades/eproc-filtro-preferencias-processo.md"}'),t={name:"funcionalidades/eproc-filtro-preferencias-processo.md"};function i(d,a,n,l,p,c){return o(),s("div",null,a[0]||(a[0]=[r('<h1 id="filtro-nas-listas-de-preferencias-do-processo" tabindex="-1">Filtro nas listas de preferências do processo <a class="header-anchor" href="#filtro-nas-listas-de-preferencias-do-processo" aria-label="Permalink to &quot;Filtro nas listas de preferências do processo&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Os painéis de preferências da página do processo (Minutas, Movimentação, Intimação e Automatizações) podem ter dezenas de itens. Este recurso coloca um campo de busca em cada painel, que filtra os itens enquanto você digita. Também permite guardar um filtro como pasta e ocultar preferências da unidade que você não usa.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, página do processo, painéis de Preferências de Minutas, Movimentação, Intimação e Automatizações, ao lado do título da lista de itens (o campo traz o logo do eploc).</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><p><strong>Filtrar</strong></p><ol><li>Abra o painel de preferências desejado.</li><li>Digite no campo de busca. Você pode usar várias palavras, em qualquer ordem: &quot;mand cita&quot; encontra &quot;Mandado de Citação&quot;. Os trechos encontrados ficam destacados.</li><li>Apague o texto para voltar a ver todos os itens.</li></ol><p><strong>Criar uma pasta</strong></p><ol><li>Digite um filtro e clique em <strong>Criar pasta</strong>. Ao passar o mouse sobre o botão, os itens que entrarão na pasta ficam realçados.</li><li>Dê um nome à pasta. Ela aparece numa faixa logo abaixo do título do painel e reúne os itens que combinam com o filtro, inclusive os que forem criados depois.</li><li>As pastas podem ser reordenadas arrastando e editadas pelo botão direito. Pelo botão direito em um item, você também pode movê-lo para outra pasta ou tirá-lo da pasta.</li></ol><p><strong>Ocultar preferências da unidade</strong></p><ol><li>Clique com o botão direito numa preferência da unidade e escolha ocultá-la.</li><li>Ela vai para a pasta <strong>Ocultadas</strong>, sempre a última da faixa, de onde pode ser reexibida.</li></ol><p>As pastas valem para todos os processos.</p><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Opção</th><th>Padrão</th><th>Efeito</th></tr></thead><tbody><tr><td>Permitir agrupar itens em pastas (&quot;Criar pasta&quot; a partir do filtro) e ocultar preferências da unidade</td><td>ligada</td><td>Desligada, fica só o campo de busca.</td></tr></tbody></table><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>Só as preferências da unidade podem ser ocultadas. As individuais você mesmo pode excluir no eproc.</li><li>Cada item fica em no máximo uma pasta.</li><li>Enquanto há um filtro digitado, as pastas com itens encontrados aparecem abertas e as demais somem. Os itens da pasta &quot;Ocultadas&quot; não aparecem na busca.</li></ul>',17)]))}const f=e(t,[["render",i]]);export{m as __pageData,f as default};
